__d(function(a,e,o,i,n,s,r){n.exports={bcms:{title:"Swear words",tip:"Swearing in the Balkans is an art form, and it is everywhere: in caf\xe9s, at football, between best friends. Most of it is cheerful frustration, not anger. The golden rules: never with grandparents, teachers or your boss; tone matters more than the word; and when a local says it with a grin, it is friendly. Strength runs from \ud83c\udf36\ufe0f (mild) to \ud83c\udf36\ufe0f\ud83c\udf36\ufe0f\ud83c\udf36\ufe0f (strong).",items:[{sr:"sranje",en:"shit / crap",lvl:2,note:"A bad situation or a rubbish thing. The everyday all-rounder.",ex:{sr:"Kakvo sranje!",en:"What a load of shit!"}},{sr:"govno",en:"shit (the actual stuff)",lvl:2,note:"The literal stuff, and also a person you cannot stand: \"govno jedno\", you piece of shit.",ex:{sr:"Ovaj film je govno.",en:"This film is shit."}},{sr:"jebiga",en:"fuck it / oh well",lvl:2,note:"The national shrug. Missed the bus? Lost again? Jebiga. More resigned than angry, and used constantly.",ex:{sr:"Pao je sneg, jebiga.",hr:"Pao je snijeg, jebiga.",bs:"Pao je snijeg, jebiga.",me:"Pao je snijeg, jebiga.",en:"It's snowed. Oh well, fuck it."}},{sr:"jebote",en:"fucking hell / wow",lvl:2,note:"Surprise, good or bad. Friends say it about a great view as often as about bad news.",ex:{sr:"Jebote, kakav pogled!",en:"Fucking hell, what a view!"}},{sr:"jebeno",en:"fucking (as in very)",lvl:2,note:"Makes anything stronger: jebeno dobro, fucking good.",ex:{sr:"Ovo je jebeno dobro.",en:"This is fucking good."}},{sr:"odjebi",en:"fuck off",lvl:3,note:"Direct and rude. Between close friends it can be a joke; with anyone else, you mean it.",ex:{sr:"Odjebi, imam posla.",en:"Fuck off, I'm busy."}},{sr:"gubi se",en:"piss off / get lost",lvl:1,note:"Rude but not shocking. Fine for a pushy seller or a cheeky friend.",ex:{sr:"Gubi se odavde!",en:"Piss off out of here!"}},{sr:"koji kurac?",en:"what the fuck?",lvl:3,note:"Literally \"which dick?\". Strong, but you will hear it every time something makes no sense.",ex:{sr:"Koji kurac radi\u0161?",en:"What the fuck are you doing?"}},{sr:"koji \u0111avo?",hr:"koji vrag?",bs:"koji vrag?",en:"what the hell?",lvl:1,note:"The polite version: the devil instead of the dick. Safe in front of most people.",ex:{sr:"Koji \u0111avo se ovde de\u0161ava?",hr:"Koji se vrag ovdje doga\u0111a?",bs:"Koji se vrag ovdje de\u0161ava?",me:"Koji se \u0111avo ovdje de\u0161ava?",en:"What the hell is going on here?"}},{sr:"do\u0111avola",hr:"dovraga",bs:"dovraga",en:"damn it",lvl:1,note:"Mild. Stub your toe, drop your keys, miss the tram.",ex:{sr:"Do\u0111avola, opet kasnim!",hr:"Dovraga, opet kasnim!",bs:"Dovraga, opet kasnim!",en:"Damn it, I'm late again!"}},{sr:"zajebava\u0161 me?",en:"are you taking the piss?",lvl:2,note:"From zajebavati, to mess about. Pure disbelief, usually half laughing.",ex:{sr:"Zajebava\u0161 me? Stvarno?",en:"Are you taking the piss? Really?"}},{sr:"ne seri",en:"stop talking shit",lvl:2,note:"From srati, to shit. Means you don't believe a word of it.",ex:{sr:"Ne seri, to nije istina.",en:"Stop talking shit, that's not true."}},{sr:"sjebano",en:"fucked up",lvl:2,note:"A situation that has gone badly wrong. Sjebao sam: I fucked up.",ex:{sr:"Sve je sjebano.",en:"Everything's fucked up."}},{sr:"boli me uvo",hr:"boli me uho",bs:"boli me uho",en:"I couldn't care less",lvl:1,note:"Literally \"my ear hurts\". Cheeky but harmless.",ex:{sr:"Boli me uvo za to.",hr:"Boli me uho za to.",bs:"Boli me uho za to.",en:"I couldn't care less about that."}},{sr:"boli me kurac",en:"I don't give a fuck",lvl:3,note:"The strong version of \"my ear hurts\", with a different body part. Very common, very rude.",ex:{sr:"Boli me kurac \u0161ta on misli.",hr:"Boli me kurac \u0161to on misli.",en:"I don't give a fuck what he thinks."}},{sr:"kreten",en:"moron / idiot",lvl:1,note:"The standard word for a bad driver. Budala and idiot work too.",ex:{sr:"Vozi kao kreten.",en:"He drives like a moron."}},{sr:"majku mu",en:"damn it! (lit. his mother)",lvl:2,note:"Short for something far ruder about someone's mother. On its own, a common burst of frustration.",ex:{sr:"Majku mu, pokvario se auto!",en:"Damn it, the car's broken down!"}}]},en:{title:{sr:"Psovke",hr:"Psovke",bs:"Psovke",me:"Psovke"},tip:{sr:"Engleski psuje druga\u010dije od nas: manje majki, vi\u0161e \"fuck\". Britanci imaju i svoje bla\u017ee re\u010di, kao \"bloody\" i \"bollocks\". Zlatna pravila: ne pred \u0161efom, nastavnikom ili bakom; ton je va\u017eniji od re\u010di; a \"fuck\" je na engleskom ozbiljniji nego \u0161to izgleda u filmovima. Ja\u010dina ide od \ud83c\udf36\ufe0f (blago) do \ud83c\udf36\ufe0f\ud83c\udf36\ufe0f\ud83c\udf36\ufe0f (jako).",hr:"Engleski psuje druk\u010dije od nas: manje majki, vi\u0161e \"fuck\". Britanci imaju i svoje bla\u017ee rije\u010di, kao \"bloody\" i \"bollocks\". Zlatna pravila: ne pred \u0161efom, nastavnikom ili bakom; ton je va\u017eniji od rije\u010di; a \"fuck\" je na engleskom ozbiljniji nego \u0161to izgleda u filmovima. Ja\u010dina ide od \ud83c\udf36\ufe0f (blago) do \ud83c\udf36\ufe0f\ud83c\udf36\ufe0f\ud83c\udf36\ufe0f (jako).",bs:"Engleski psuje druga\u010dije od nas: manje majki, vi\u0161e \"fuck\". Britanci imaju i svoje bla\u017ee rije\u010di, kao \"bloody\" i \"bollocks\". Zlatna pravila: ne pred \u0161efom, nastavnikom ili nanom; ton je va\u017eniji od rije\u010di; a \"fuck\" je na engleskom ozbiljniji nego \u0161to izgleda u filmovima. Ja\u010dina ide od \ud83c\udf36\ufe0f (blago) do \ud83c\udf36\ufe0f\ud83c\udf36\ufe0f\ud83c\udf36\ufe0f (jako).",me:"Engleski psuje druga\u010dije od nas: manje majki, vi\u0161e \"fuck\". Britanci imaju i svoje bla\u017ee rije\u010di, kao \"bloody\" i \"bollocks\". Zlatna pravila: ne pred \u0161efom, nastavnikom ili bakom; ton je va\u017eniji od rije\u010di; a \"fuck\" je na engleskom ozbiljniji nego \u0161to izgleda u filmovima. Ja\u010dina ide od \ud83c\udf36\ufe0f (blago) do \ud83c\udf36\ufe0f\ud83c\udf36\ufe0f\ud83c\udf36\ufe0f (jako)."},items:[{en:"shit",sr:"sranje",lvl:2,note:{sr:"Svestrana re\u010d: lo\u0161a situacija, lo\u0161a stvar ili uzvik kad ne\u0161to po\u0111e naopako.",hr:"Svestrana rije\u010d: lo\u0161a situacija, lo\u0161a stvar ili uzvik kad ne\u0161to po\u0111e naopako.",bs:"Svestrana rije\u010d: lo\u0161a situacija, lo\u0161a stvar ili uzvik kad ne\u0161to po\u0111e naopako.",me:"Svestrana rije\u010d: lo\u0161a situacija, lo\u0161a stvar ili uzvik kad ne\u0161to po\u0111e naopako."},ex:{en:"Oh shit, I forgot my keys.",sr:"Sranje, zaboravio sam klju\u010deve."}},{en:"crap",sr:"bezveze, sme\u0107e (bla\u017ee)",lvl:1,note:{sr:"Bla\u017ea verzija od \"shit\". Mo\u017ee i pred ve\u0107inom ljudi.",hr:"Bla\u017ea verzija od \"shit\". Mo\u017ee i pred ve\u0107inom ljudi.",bs:"Bla\u017ea verzija od \"shit\". Mo\u017ee i pred ve\u0107inom ljudi.",me:"Bla\u017ea verzija od \"shit\". Mo\u017ee i pred ve\u0107inom ljudi."},ex:{en:"This film is crap.",sr:"Ovaj film je bezveze."}},{en:"bloody hell",sr:"bo\u017ee mili (britanski)",lvl:1,note:{sr:"\u010cisto britanski uzvik iznena\u0111enja ili besa. Zvu\u010di jako, a zapravo je blag.",hr:"\u010cisto britanski uzvik iznena\u0111enja ili bijesa. Zvu\u010di jako, a zapravo je blag.",bs:"\u010cisto britanski uzvik iznena\u0111enja ili bijesa. Zvu\u010di jako, a zapravo je blag.",me:"\u010cisto britanski uzvik iznena\u0111enja ili bijesa. Zvu\u010di jako, a zapravo je blag."},ex:{en:"Bloody hell, it's cold!",sr:"Bo\u017ee mili, kako je hladno!"}},{en:"damn it",sr:"do\u0111avola",hr:"dovraga",bs:"dovraga",lvl:1,note:{sr:"Blag uzvik frustracije. Mo\u017ee skoro svuda.",hr:"Blag uzvik frustracije. Mo\u017ee skoro svuda.",bs:"Blag uzvik frustracije. Mo\u017ee skoro svuda.",me:"Blag uzvik frustracije. Mo\u017ee skoro svuda."},ex:{en:"Damn it, I missed the bus.",sr:"Do\u0111avola, propustio sam autobus.",hr:"Dovraga, propustio sam autobus.",bs:"Dovraga, propustio sam autobus."}},{en:"piss off",sr:"gubi se",lvl:2,note:{sr:"Britansko \"gubi se\". Grubo, ali ne \u0161okantno. Pazi, \"pissed off\" zna\u010di ne\u0161to drugo.",hr:"Britansko \"gubi se\". Grubo, ali ne \u0161okantno. Pazi, \"pissed off\" zna\u010di ne\u0161to drugo.",bs:"Britansko \"gubi se\". Grubo, ali ne \u0161okantno. Pazi, \"pissed off\" zna\u010di ne\u0161to drugo.",me:"Britansko \"gubi se\". Grubo, ali ne \u0161okantno. Pazi, \"pissed off\" zna\u010di ne\u0161to drugo."},ex:{en:"Piss off and leave me alone.",sr:"Gubi se i ostavi me na miru."}},{en:"pissed off",sr:"besan, iznerviran",hr:"bijesan, iznerviran",bs:"bijesan, iznerviran",me:"bijesan, iznerviran",lvl:1,note:{sr:"Ne psuje\u0161 nikoga, samo ka\u017ee\u0161 da si ljut. Vrlo \u010desto u svakodnevnom govoru.",hr:"Ne psuje\u0161 nikoga, samo ka\u017ee\u0161 da si ljut. Vrlo \u010desto u svakodnevnom govoru.",bs:"Ne psuje\u0161 nikoga, samo ka\u017ee\u0161 da si ljut. Vrlo \u010desto u svakodnevnom govoru.",me:"Ne psuje\u0161 nikoga, samo ka\u017ee\u0161 da si ljut. Vrlo \u010desto u svakodnevnom govoru."},ex:{en:"I'm really pissed off with him.",sr:"Ba\u0161 sam besan na njega.",hr:"Ba\u0161 sam bijesan na njega.",bs:"Ba\u0161 sam bijesan na njega.",me:"Ba\u0161 sam bijesan na njega."}},{en:"pissed",sr:"pijan (britanski)",lvl:1,note:{sr:"Pazi na razliku! U Britaniji \"pissed\" zna\u010di pijan, a u Americi ljut.",hr:"Pazi na razliku! U Britaniji \"pissed\" zna\u010di pijan, a u Americi ljut.",bs:"Pazi na razliku! U Britaniji \"pissed\" zna\u010di pijan, a u Americi ljut.",me:"Pazi na razliku! U Britaniji \"pissed\" zna\u010di pijan, a u Americi ljut."},ex:{en:"He was pissed at the party.",sr:"Bio je pijan na \u017eurci.",hr:"Bio je pijan na zabavi."}},{en:"fuck off",sr:"odjebi",lvl:3,note:{sr:"Direktno i grubo. Me\u0111u bliskim prijateljima mo\u017ee kao \u0161ala, sa svima ostalima misli\u0161 ozbiljno.",hr:"Izravno i grubo. Me\u0111u bliskim prijateljima mo\u017ee kao \u0161ala, sa svima ostalima misli\u0161 ozbiljno.",bs:"Direktno i grubo. Me\u0111u bliskim prijateljima mo\u017ee kao \u0161ala, sa svima ostalima misli\u0161 ozbiljno.",me:"Direktno i grubo. Me\u0111u bliskim prijateljima mo\u017ee kao \u0161ala, sa svima ostalima misli\u0161 ozbiljno."},ex:{en:"Fuck off, I'm busy.",sr:"Odjebi, imam posla."}},{en:"what the fuck?",sr:"koji kurac?",lvl:3,note:{sr:"Jako, ali se \u010duje svuda kad ne\u0161to nema smisla. U porukama \u010desto samo \"WTF\".",hr:"Jako, ali se \u010duje svuda kad ne\u0161to nema smisla. U porukama \u010desto samo \"WTF\".",bs:"Jako, ali se \u010duje svuda kad ne\u0161to nema smisla. U porukama \u010desto samo \"WTF\".",me:"Jako, ali se \u010duje svuda kad ne\u0161to nema smisla. U porukama \u010desto samo \"WTF\"."},ex:{en:"What the fuck are you doing?",sr:"Koji kurac radi\u0161?"}},{en:"what the hell?",sr:"koji \u0111avo?",hr:"koji vrag?",bs:"koji vrag?",lvl:1,note:{sr:"Pristojnija verzija. Mo\u017ee i pred roditeljima.",hr:"Pristojnija ina\u010dica. Mo\u017ee i pred roditeljima.",bs:"Pristojnija verzija. Mo\u017ee i pred roditeljima.",me:"Pristojnija verzija. Mo\u017ee i pred roditeljima."},ex:{en:"What the hell is that?",sr:"Koji je to \u0111avo?",hr:"Koji je to vrag?",bs:"Koji je to vrag?"}},{en:"fuck it",sr:"jebiga",lvl:2,note:{sr:"Kao na\u0161e \"jebiga\": odustajanje uz osmeh. Ali na engleskom zvu\u010di ja\u010de nego kod nas.",hr:"Kao na\u0161e \"jebiga\": odustajanje uz osmijeh. Ali na engleskom zvu\u010di ja\u010de nego kod nas.",bs:"Kao na\u0161e \"jebiga\": odustajanje uz osmijeh. Ali na engleskom zvu\u010di ja\u010de nego kod nas.",me:"Kao na\u0161e \"jebiga\": odustajanje uz osmijeh. Ali na engleskom zvu\u010di ja\u010de nego kod nas."},ex:{en:"Fuck it, let's order pizza.",sr:"Jebiga, hajde da naru\u010dimo picu.",hr:"Jebiga, naru\u010dimo pizzu."}},{en:"fucking hell",sr:"jebote",lvl:2,note:{sr:"Iznena\u0111enje ili bes, isto kao na\u0161e \"jebote\".",hr:"Iznena\u0111enje ili bijes, isto kao na\u0161e \"jebote\".",bs:"Iznena\u0111enje ili bijes, isto kao na\u0161e \"jebote\".",me:"Iznena\u0111enje ili bijes, isto kao na\u0161e \"jebote\"."},ex:{en:"Fucking hell, that was close!",sr:"Jebote, to je bilo blizu!"}},{en:"bollocks",sr:"gluposti (britanski)",lvl:2,note:{sr:"Doslovno \"jaja\", ali zna\u010di \"gluposti\". Veoma britanski.",hr:"Doslovno \"jaja\", ali zna\u010di \"gluposti\". Vrlo britanski.",bs:"Doslovno \"jaja\", ali zna\u010di \"gluposti\". Vrlo britanski.",me:"Doslovno \"jaja\", ali zna\u010di \"gluposti\". Veoma britanski."},ex:{en:"That's a load of bollocks.",sr:"To su obi\u010dne gluposti."}},{en:"bullshit",sr:"ne seri, la\u017e",lvl:2,note:{sr:"Kad ne veruje\u0161 ni re\u010d. \"Bullshit!\" je kao na\u0161e \"ne seri!\"",hr:"Kad ne vjeruje\u0161 ni rije\u010d. \"Bullshit!\" je kao na\u0161e \"ne seri!\"",bs:"Kad ne vjeruje\u0161 ni rije\u010d. \"Bullshit!\" je kao na\u0161e \"ne seri!\"",me:"Kad ne vjeruje\u0161 ni rije\u010d. \"Bullshit!\" je kao na\u0161e \"ne seri!\""},ex:{en:"That's bullshit and you know it.",sr:"To je la\u017e i ti to zna\u0161."}},{en:"are you taking the piss?",sr:"zajebava\u0161 me?",lvl:2,note:{sr:"Britanski izraz: misli\u0161 da se neko \u0161ali s tobom ili te ismeva.",hr:"Britanski izraz: misli\u0161 da se netko \u0161ali s tobom ili te ismijava.",bs:"Britanski izraz: misli\u0161 da se neko \u0161ali s tobom ili te ismijava.",me:"Britanski izraz: misli\u0161 da se neko \u0161ali sa tobom ili te ismijava."},ex:{en:"Five pounds for a coffee? Are you taking the piss?",sr:"Pet funti za kafu? Zajebava\u0161 me?",hr:"Pet funti za kavu? Zajebava\u0161 me?",bs:"Pet funti za kahvu? Zajebava\u0161 me?"}},{en:"I couldn't care less",sr:"boli me uvo",hr:"boli me uho",bs:"boli me uho",lvl:1,note:{sr:"Pristojan na\u010din da ka\u017ee\u0161 da te nije briga.",hr:"Pristojan na\u010din da ka\u017ee\u0161 da te nije briga.",bs:"Pristojan na\u010din da ka\u017ee\u0161 da te nije briga.",me:"Pristojan na\u010din da ka\u017ee\u0161 da te nije briga."},ex:{en:"I couldn't care less what he thinks.",sr:"Boli me uvo \u0161ta on misli.",hr:"Boli me uho \u0161to on misli.",bs:"Boli me uho \u0161ta on misli."}},{en:"I don't give a fuck",sr:"boli me kurac",lvl:3,note:{sr:"Ista poruka, samo mnogo grublje.",hr:"Ista poruka, samo mnogo grublje.",bs:"Ista poruka, samo mnogo grublje.",me:"Ista poruka, samo mnogo grublje."},ex:{en:"I don't give a fuck about football.",sr:"Boli me kurac za fudbal.",hr:"Boli me kurac za nogomet."}},{en:"dickhead",sr:"kreten (prosta\u010dki)",lvl:2,note:{sr:"\u010cesta britanska uvreda za nekoga ko se pona\u0161a glupo.",hr:"\u010cesta britanska uvreda za nekoga tko se pona\u0161a glupo.",bs:"\u010cesta britanska uvreda za nekoga tko se pona\u0161a glupo.",me:"\u010cesta britanska uvreda za nekoga ko se pona\u0161a glupo."},ex:{en:"Some dickhead took my parking space.",sr:"Neki kreten mi je uzeo parking mesto.",hr:"Neki kreten mi je uzeo parkirno mjesto.",bs:"Neki kreten mi je uzeo parking mjesto.",me:"Neki kreten mi je uzeo parking mjesto."}}]},de:{title:{sr:"Psovke",hr:"Psovke",bs:"Psovke",me:"Psovke"},tip:{sr:"Nemci psuju druga\u010dije od nas: skoro nikad o majkama, a skoro uvek o Schei\xdfe. Na\u0161e psovanje im zvu\u010di \u0161okantno ma\u0161tovito, pa ono \u0161to je kod nas obi\u010dna \u0161ala njih mo\u017ee ozbiljno da uvredi. Zlatna pravila: nikad na poslu, nikad pred slu\u017ebenicima (Ausl\xe4nderbeh\xf6rde, policija, Jobcenter), a svi kojima persira\u0161, dakle sa kojima si na Sie, potpuno su zabranjena zona. Pazi se i zbog zakona: uvreda (Beleidigung) u Nema\u010dkoj mo\u017ee da se zavr\u0161i nov\u010danom kaznom. Ja\u010dina ide od \ud83c\udf36\ufe0f (blago) do \ud83c\udf36\ufe0f\ud83c\udf36\ufe0f\ud83c\udf36\ufe0f (jako).",hr:"Nijemci psuju druk\u010dije od nas: gotovo nikad o majkama, a gotovo uvijek o Schei\xdfe. Na\u0161e im psovanje zvu\u010di \u0161okantno ma\u0161tovito, pa ono \u0161to je kod nas obi\u010dna \u0161ala njih mo\u017ee ozbiljno uvrijediti. Zlatna pravila: nikad na poslu, nikad pred slu\u017ebenicima (Ausl\xe4nderbeh\xf6rde, policija, Jobcenter), a svi kojima persira\u0161, dakle s kojima si na Sie, potpuno su zabranjena zona. Pazi se i zbog zakona: uvreda (Beleidigung) u Njema\u010dkoj mo\u017ee zavr\u0161iti nov\u010danom kaznom. Ja\u010dina ide od \ud83c\udf36\ufe0f (blago) do \ud83c\udf36\ufe0f\ud83c\udf36\ufe0f\ud83c\udf36\ufe0f (jako).",bs:"Nijemci psuju druga\u010dije od nas: skoro nikad o majkama, a skoro uvijek o Schei\xdfe. Na\u0161e psovanje im zvu\u010di \u0161okantno ma\u0161tovito, pa ono \u0161to je kod nas obi\u010dna \u0161ala njih mo\u017ee ozbiljno uvrijediti. Zlatna pravila: nikad na poslu, nikad pred slu\u017ebenicima (Ausl\xe4nderbeh\xf6rde, policija, Jobcenter), a svi kojima persira\u0161, dakle s kojima si na Sie, potpuno su zabranjena zona. Pazi se i zbog zakona: uvreda (Beleidigung) u Njema\u010dkoj mo\u017ee zavr\u0161iti nov\u010danom kaznom. Ja\u010dina ide od \ud83c\udf36\ufe0f (blago) do \ud83c\udf36\ufe0f\ud83c\udf36\ufe0f\ud83c\udf36\ufe0f (jako).",me:"Nijemci psuju druga\u010dije od nas: skoro nikad o majkama, a skoro uvijek o Schei\xdfe. Na\u0161e psovanje im zvu\u010di \u0161okantno ma\u0161tovito, pa ono \u0161to je kod nas obi\u010dna \u0161ala njih mo\u017ee ozbiljno da uvrijedi. Zlatna pravila: nikad na poslu, nikad pred slu\u017ebenicima (Ausl\xe4nderbeh\xf6rde, policija, Jobcenter), a svi kojima persira\u0161, dakle sa kojima si na Sie, potpuno su zabranjena zona. Pazi se i zbog zakona: uvreda (Beleidigung) u Njema\u010dkoj mo\u017ee da se zavr\u0161i nov\u010danom kaznom. Ja\u010dina ide od \ud83c\udf36\ufe0f (blago) do \ud83c\udf36\ufe0f\ud83c\udf36\ufe0f\ud83c\udf36\ufe0f (jako)."},items:[{de:"Schei\xdfe",sr:"sranje",lvl:2,note:{sr:"Naj\u010de\u0161\u0107a nema\u010dka psovka, za sve \u0161to po\u0111e naopako. Me\u0111u prijateljima je sasvim normalna, otprilike kao na\u0161e \"sranje\". Ali ne pred \u0161efom (Chef), na \u0161alteru u Ausl\xe4nderbeh\xf6rde ili pred stanodavcem.",hr:"Naj\u010de\u0161\u0107a njema\u010dka psovka, za sve \u0161to po\u0111e naopako. Me\u0111u prijateljima je posve normalna, otprilike kao na\u0161e \"sranje\". Ali ne pred \u0161efom (Chef), na \u0161alteru u Ausl\xe4nderbeh\xf6rde ili pred stanodavcem.",bs:"Naj\u010de\u0161\u0107a njema\u010dka psovka, za sve \u0161to po\u0111e naopako. Me\u0111u prijateljima je sasvim normalna, otprilike kao na\u0161e \"sranje\". Ali ne pred \u0161efom (Chef), na \u0161alteru u Ausl\xe4nderbeh\xf6rde ili pred stanodavcem.",me:"Naj\u010de\u0161\u0107a njema\u010dka psovka, za sve \u0161to po\u0111e naopako. Me\u0111u prijateljima je sasvim normalna, otprilike kao na\u0161e \"sranje\". Ali ne pred \u0161efom (Chef), na \u0161alteru u Ausl\xe4nderbeh\xf6rde ili pred stanodavcem."},ex:{de:"Schei\xdfe, ich habe den Bus verpasst!",sr:"Sranje, propustio sam autobus!"}},{de:"Mist",sr:"sme\u0107e, bezveze (blago)",lvl:1,note:{sr:"Doslovno \"stajsko \u0111ubrivo\", a zna\u010di sme\u0107e ili glupost. Najbla\u017ea nema\u010dka psovka, \u010duje se i od dece i od baka. Prolazi skoro svuda, \u010dak i na poslu kad ti ne\u0161to ispadne iz ruke, samo ne nazivaj tako ne\u010diji rad pred tom osobom.",hr:"Doslovno \"gnoj\" (stajsko gnojivo), a zna\u010di sme\u0107e ili glupost. Najbla\u017ea njema\u010dka psovka, \u010duje se i od djece i od baka. Prolazi gotovo svugdje, \u010dak i na poslu kad ti ne\u0161to ispadne iz ruke, samo nemoj tako nazvati ne\u010diji rad pred tom osobom.",bs:"Doslovno \"stajsko \u0111ubrivo\", a zna\u010di sme\u0107e ili glupost. Najbla\u017ea njema\u010dka psovka, \u010duje se i od djece i od nana. Prolazi skoro svugdje, \u010dak i na poslu kad ti ne\u0161to ispadne iz ruke, samo ne nazivaj tako ne\u010diji rad pred tom osobom.",me:"Doslovno \"stajsko \u0111ubrivo\", a zna\u010di sme\u0107e ili glupost. Najbla\u017ea njema\u010dka psovka, \u010duje se i od djece i od baka. Prolazi skoro svuda, \u010dak i na poslu kad ti ne\u0161to ispadne iz ruke, samo ne nazivaj tako ne\u010diji rad pred tom osobom."},ex:{de:"Der Film war echt Mist.",sr:"Film je bio ba\u0161 bezveze."}},{de:"verdammt",sr:"do\u0111avola",hr:"dovraga",bs:"dovraga",lvl:1,note:{sr:"Blag uzvik kad ne\u0161to krene naopako, kao na\u0161e \"do\u0111avola\". Mo\u017ee i kao poja\u010diva\u010d: \"verdammt gut\", vra\u0161ki dobro. Prolazi i pred starijima, ali ne u formalnom razgovoru sa nekim kome persira\u0161.",hr:"Blag uzvik kad ne\u0161to krene naopako, kao na\u0161e \"dovraga\". Mo\u017ee i kao poja\u010diva\u010d: \"verdammt gut\", vra\u0161ki dobro. Prolazi i pred starijima, ali ne u slu\u017ebenom razgovoru s nekim kome persira\u0161.",bs:"Blag uzvik kad ne\u0161to krene naopako, kao na\u0161e \"dovraga\". Mo\u017ee i kao poja\u010diva\u010d: \"verdammt gut\", vra\u0161ki dobro. Prolazi i pred starijima, ali ne u formalnom razgovoru s nekim kome persira\u0161.",me:"Blag uzvik kad ne\u0161to krene naopako, kao na\u0161e \"do\u0111avola\". Mo\u017ee i kao poja\u010diva\u010d: \"verdammt gut\", vra\u0161ki dobro. Prolazi i pred starijima, ali ne u formalnom razgovoru sa nekim kome persira\u0161."},ex:{de:"Verdammt, wo ist mein Handy?",sr:"Do\u0111avola, gde mi je telefon?",hr:"Dovraga, gdje mi je mobitel?",bs:"Dovraga, gdje mi je telefon?",me:"Do\u0111avola, gdje mi je telefon?"}},{de:"verdammt noch mal",sr:"majku mu",lvl:2,note:{sr:"Ja\u010da verzija od \"verdammt\", kad ti je stvarno dosta. Kao na\u0161e \"majku mu\", samo bez i\u010dije majke. Vi\u010de se na printer ili na kom\u0161ijinog psa, a nikad na kolegu, \u0161efa ili slu\u017ebenika.",hr:"Ja\u010da ina\u010dica od \"verdammt\", kad ti je stvarno dosta. Kao na\u0161e \"majku mu\", samo bez i\u010dije majke. Vi\u010de se na pisa\u010d ili na susjedova psa, a nikad na kolegu, \u0161efa ili slu\u017ebenika.",bs:"Ja\u010da verzija od \"verdammt\", kad ti je stvarno dosta. Kao na\u0161e \"majku mu\", samo bez i\u010dije majke. Vi\u010de se na printer ili na kom\u0161ijinog psa, a nikad na kolegu, \u0161efa ili slu\u017ebenika.",me:"Ja\u010da verzija od \"verdammt\", kad ti je stvarno dosta. Kao na\u0161e \"majku mu\", samo bez i\u010dije majke. Vi\u010de se na printer ili na kom\u0161ijinog psa, a nikad na kolegu, \u0161efa ili slu\u017ebenika."},ex:{de:"Verdammt noch mal, h\xf6r mir endlich zu!",sr:"Majku mu, saslu\u0161aj me ve\u0107 jednom!"}},{de:"schei\xdfegal",sr:"boli me uvo",hr:"boli me uho",bs:"boli me uho",lvl:2,note:{sr:"Kad te ne\u0161to ba\u0161 uop\u0161te ne zanima: \"Das ist mir schei\xdfegal.\" Ja\u010de od obi\u010dnog \"egal\" (svejedno) i zvu\u010di prili\u010dno grubo. Nikad ga ne govori o poslu, papirima ili ne\u010dijem problemu pred tom osobom.",hr:"Kad te ne\u0161to ba\u0161 uop\u0107e ne zanima: \"Das ist mir schei\xdfegal.\" Ja\u010de od obi\u010dnog \"egal\" (svejedno) i zvu\u010di prili\u010dno grubo. Nikad ga ne govori o poslu, papirima ili ne\u010dijem problemu pred tom osobom.",bs:"Kad te ne\u0161to ba\u0161 uop\u0107e ne zanima: \"Das ist mir schei\xdfegal.\" Ja\u010de od obi\u010dnog \"egal\" (svejedno) i zvu\u010di prili\u010dno grubo. Nikad ga ne govori o poslu, papirima ili ne\u010dijem problemu pred tom osobom.",me:"Kad te ne\u0161to ba\u0161 uop\u0161te ne zanima: \"Das ist mir schei\xdfegal.\" Ja\u010de od obi\u010dnog \"egal\" (svejedno) i zvu\u010di prili\u010dno grubo. Nikad ga ne govori o poslu, papirima ili ne\u010dijem problemu pred tom osobom."},ex:{de:"Was die Nachbarn denken, ist mir schei\xdfegal.",sr:"Boli me uvo \u0161ta misle kom\u0161ije.",hr:"Boli me uho \u0161to misle susjedi.",bs:"Boli me uho \u0161ta misle kom\u0161ije."}},{de:"verpiss dich",sr:"odjebi",lvl:3,note:{sr:"Grubo i ozbiljno, otprilike kao na\u0161e \"odjebi\". Nemci ga ne bacaju olako: ako ga ka\u017ee\u0161, sva\u0111a je po\u010dela. Samo iz \u0161ale sa najboljim drugom, nikad sa nekim koga ne poznaje\u0161 dobro.",hr:"Grubo i ozbiljno, otprilike kao na\u0161e \"odjebi\". Nijemci ga ne bacaju olako: ako ga ka\u017ee\u0161, sva\u0111a je po\u010dela. Samo iz \u0161ale s najboljim prijateljem, nikad s nekim koga ne poznaje\u0161 dobro.",bs:"Grubo i ozbiljno, otprilike kao na\u0161e \"odjebi\". Nijemci ga ne bacaju olako: ako ga ka\u017ee\u0161, sva\u0111a je po\u010dela. Samo iz \u0161ale s najboljim drugom, nikad s nekim koga ne poznaje\u0161 dobro.",me:"Grubo i ozbiljno, otprilike kao na\u0161e \"odjebi\". Nijemci ga ne bacaju olako: ako ga ka\u017ee\u0161, sva\u0111a je po\u010dela. Samo iz \u0161ale sa najboljim drugom, nikad sa nekim koga ne poznaje\u0161 dobro."},ex:{de:"Verpiss dich und lass mich in Ruhe!",sr:"Odjebi i ostavi me na miru!"}},{de:"hau ab",sr:"gubi se",lvl:1,note:{sr:"Zna\u010di \"gubi se\" ili \"be\u017ei odavde\". Grubo, ali ne \u0161okantno: ka\u017ee se dosadnom mla\u0111em bratu ili golubu na balkonu. \u0160efu, kom\u0161iji ili policajcu nikako.",hr:"Zna\u010di \"gubi se\" ili \"bje\u017ei odavde\". Grubo, ali ne \u0161okantno: ka\u017ee se dosadnom mla\u0111em bratu ili golubu na balkonu. \u0160efu, susjedu ili policajcu nikako.",bs:"Zna\u010di \"gubi se\" ili \"bje\u017ei odavde\". Grubo, ali ne \u0161okantno: ka\u017ee se dosadnom mla\u0111em bratu ili golubu na balkonu. \u0160efu, kom\u0161iji ili policajcu nikako.",me:"Zna\u010di \"gubi se\" ili \"bje\u017ei odavde\". Grubo, ali ne \u0161okantno: ka\u017ee se dosadnom mla\u0111em bratu ili golubu na balkonu. \u0160efu, kom\u0161iji ili policajcu nikako."},ex:{de:"Hau ab, ich will allein sein!",sr:"Gubi se, ho\u0107u da budem sam!",hr:"Gubi se, \u017eelim biti sam!"}},{de:"was zum Teufel?",sr:"koji \u0111avo?",hr:"koji vrag?",bs:"koji vrag?",lvl:1,note:{sr:"Doslovno \"\u0161ta do \u0111avola?\". Pristojna verzija za iznena\u0111enje ili ljutnju, mo\u017ee\u0161 je re\u0107i i pred roditeljima. Sa nekim kome persira\u0161 ipak izbegavaj.",hr:"Doslovno \"\u0161to do vraga?\". Pristojna ina\u010dica za iznena\u0111enje ili ljutnju, mo\u017ee\u0161 je re\u0107i i pred roditeljima. S nekim kome persira\u0161 ipak izbjegavaj.",bs:"Doslovno \"\u0161ta do vraga?\". Pristojna verzija za iznena\u0111enje ili ljutnju, mo\u017ee\u0161 je re\u0107i i pred roditeljima. S nekim kome persira\u0161 ipak izbjegavaj.",me:"Doslovno \"\u0161ta do \u0111avola?\". Pristojna verzija za iznena\u0111enje ili ljutnju, mo\u017ee\u0161 je re\u0107i i pred roditeljima. Sa nekim kome persira\u0161 ipak izbjegavaj."},ex:{de:"Was zum Teufel machst du da?",sr:"\u0160ta to, do\u0111avola, radi\u0161?",hr:"\u0160to to, dovraga, radi\u0161?",bs:"\u0160ta to, dovraga, radi\u0161?"}},{de:"was soll der Schei\xdf?",sr:"\u010demu ovo sranje?",lvl:2,note:{sr:"Kad ne\u0161to nema smisla ili te neko nervira: \"\u010demu ovo sranje?\". Pazi na rod: ovde je \"der Schei\xdf\", bez e na kraju. Zvu\u010di ljuto i grubo, pa ga \u010duvaj za prijatelje. Na poslu ili u nekoj slu\u017ebi zvu\u010di kao napad.",hr:"Kad ne\u0161to nema smisla ili te netko \u017eivcira: \"\u010demu ovo sranje?\". Pazi na rod: ovdje je \"der Schei\xdf\", bez e na kraju. Zvu\u010di ljutito i grubo, pa ga \u010duvaj za prijatelje. Na poslu ili u nekom uredu zvu\u010di kao napad.",bs:"Kad ne\u0161to nema smisla ili te neko nervira: \"\u010demu ovo sranje?\". Pazi na rod: ovdje je \"der Schei\xdf\", bez e na kraju. Zvu\u010di ljuto i grubo, pa ga \u010duvaj za prijatelje. Na poslu ili u nekoj slu\u017ebi zvu\u010di kao napad.",me:"Kad ne\u0161to nema smisla ili te neko nervira: \"\u010demu ovo sranje?\". Pazi na rod: ovdje je \"der Schei\xdf\", bez e na kraju. Zvu\u010di ljuto i grubo, pa ga \u010duvaj za prijatelje. Na poslu ili u nekoj slu\u017ebi zvu\u010di kao napad."},ex:{de:"Was soll der Schei\xdf? Das ist mein Parkplatz!",sr:"\u010cemu ovo sranje? To je moje parking mesto!",hr:"\u010cemu ovo sranje? To je moje parkirno mjesto!",bs:"\u010cemu ovo sranje? To je moje parking mjesto!",me:"\u010cemu ovo sranje? To je moje parking mjesto!"}},{de:"Quatsch",sr:"gluposti",lvl:1,note:{sr:"Zna\u010di \"gluposti\" i uop\u0161te nije psovka. Nemci ga koriste stalno, \u010dak i u kancelariji me\u0111u kolegama. Samo nemoj tako da odgovori\u0161 slu\u017ebeniku ili lekaru, zvu\u010da\u0107e kao da ih ne shvata\u0161 ozbiljno.",hr:"Zna\u010di \"gluposti\" i uop\u0107e nije psovka. Nijemci ga koriste stalno, \u010dak i u uredu me\u0111u kolegama. Samo nemoj tako odgovoriti slu\u017ebeniku ili lije\u010dniku, zvu\u010dat \u0107e kao da ih ne shva\u0107a\u0161 ozbiljno.",bs:"Zna\u010di \"gluposti\" i uop\u0107e nije psovka. Nijemci ga koriste stalno, \u010dak i u kancelariji me\u0111u kolegama. Samo nemoj tako odgovoriti slu\u017ebeniku ili ljekaru, zvu\u010dat \u0107e kao da ih ne shvata\u0161 ozbiljno.",me:"Zna\u010di \"gluposti\" i uop\u0161te nije psovka. Nijemci ga koriste stalno, \u010dak i u kancelariji me\u0111u kolegama. Samo nemoj tako da odgovori\u0161 slu\u017ebeniku ili ljekaru, zvu\u010da\u0107e kao da ih ne shvata\u0161 ozbiljno."},ex:{de:"Quatsch, das stimmt doch gar nicht!",sr:"Gluposti, to uop\u0161te nije ta\u010dno!",hr:"Gluposti, to uop\u0107e nije to\u010dno!",bs:"Gluposti, to uop\u0107e nije ta\u010dno!"}},{de:"der Idiot",sr:"idiot, budala",lvl:1,note:{sr:"Isto kao kod nas, a \u010duje se i \"der Depp\" (vi\u0161e na jugu). Blago za na\u0161e u\u0161i, ali pazi: uvreda (Beleidigung) je u Nema\u010dkoj ka\u017enjiva, pa zbog re\u010di \"Idiot\" upu\u0107ene policajcu ili drugom voza\u010du mo\u017ee\u0161 da plati\u0161 kaznu.",hr:"Isto kao kod nas, a \u010duje se i \"der Depp\" (vi\u0161e na jugu). Blago za na\u0161e u\u0161i, ali pazi: uvreda (Beleidigung) je u Njema\u010dkoj ka\u017enjiva, pa zbog rije\u010di \"Idiot\" upu\u0107ene policajcu ili drugom voza\u010du mo\u017ee\u0161 platiti kaznu.",bs:"Isto kao kod nas, a \u010duje se i \"der Depp\" (vi\u0161e na jugu). Blago za na\u0161e u\u0161i, ali pazi: uvreda (Beleidigung) je u Njema\u010dkoj ka\u017enjiva, pa zbog rije\u010di \"Idiot\" upu\u0107ene policajcu ili drugom voza\u010du mo\u017ee\u0161 platiti kaznu.",me:"Isto kao kod nas, a \u010duje se i \"der Depp\" (vi\u0161e na jugu). Blago za na\u0161e u\u0161i, ali pazi: uvreda (Beleidigung) je u Njema\u010dkoj ka\u017enjiva, pa zbog rije\u010di \"Idiot\" upu\u0107ene policajcu ili drugom voza\u010du mo\u017ee\u0161 da plati\u0161 kaznu."},ex:{de:"Dieser Idiot hat mir die Vorfahrt genommen!",sr:"Ovaj idiot mi nije dao prednost!"}},{de:"Halt die Klappe!",sr:"za\u010depi!",lvl:1,note:{sr:"Doslovno \"dr\u017ei poklopac\", a zna\u010di \"za\u010depi\". Grubo, ali ne prosta\u010dki. \"Halt die Fresse!\" je mnogo ja\u010de (\ud83c\udf36\ufe0f\ud83c\udf36\ufe0f\ud83c\udf36\ufe0f). Nikad kolegi, \u0161efu ili nekome kome persira\u0161.",hr:"Doslovno \"dr\u017ei poklopac\", a zna\u010di \"za\u010depi\". Grubo, ali ne prosta\u010dki. \"Halt die Fresse!\" je puno ja\u010de (\ud83c\udf36\ufe0f\ud83c\udf36\ufe0f\ud83c\udf36\ufe0f). Nikad kolegi, \u0161efu ili nekome kome persira\u0161.",bs:"Doslovno \"dr\u017ei poklopac\", a zna\u010di \"za\u010depi\". Grubo, ali ne prosta\u010dki. \"Halt die Fresse!\" je mnogo ja\u010de (\ud83c\udf36\ufe0f\ud83c\udf36\ufe0f\ud83c\udf36\ufe0f). Nikad kolegi, \u0161efu ili nekome kome persira\u0161.",me:"Doslovno \"dr\u017ei poklopac\", a zna\u010di \"za\u010depi\". Grubo, ali ne prosta\u010dki. \"Halt die Fresse!\" je mnogo ja\u010de (\ud83c\udf36\ufe0f\ud83c\udf36\ufe0f\ud83c\udf36\ufe0f). Nikad kolegi, \u0161efu ili nekome kome persira\u0161."},ex:{de:"Halt die Klappe, ich will den Film sehen!",sr:"Za\u010depi, ho\u0107u da gledam film!",hr:"Za\u010depi, \u017eelim gledati film!"}},{de:"das Arschloch",sr:"\u0161upak",lvl:3,note:{sr:"Doslovno \"\u0161upak\", i Nemcima je to ozbiljna uvreda, mnogo te\u017ea nego \u0161to nama zvu\u010di. Ako ga ka\u017ee\u0161 nekome u lice, ra\u010dunaj na sva\u0111u, a mo\u017eda i na prijavu policiji. Nikad nikome na poslu, u slu\u017ebi ili u kom\u0161iluku.",hr:"Doslovno \"\u0161upak\", i Nijemcima je to ozbiljna uvreda, puno te\u017ea nego \u0161to nama zvu\u010di. Ako ga ka\u017ee\u0161 nekome u lice, ra\u010dunaj na sva\u0111u, a mo\u017eda i na prijavu policiji. Nikad nikome na poslu, u uredu ili u susjedstvu.",bs:"Doslovno \"\u0161upak\", i Nijemcima je to ozbiljna uvreda, mnogo te\u017ea nego \u0161to nama zvu\u010di. Ako ga ka\u017ee\u0161 nekome u lice, ra\u010dunaj na sva\u0111u, a mo\u017eda i na prijavu policiji. Nikad nikome na poslu, u slu\u017ebi ili u kom\u0161iluku.",me:"Doslovno \"\u0161upak\", i Nijemcima je to ozbiljna uvreda, mnogo te\u017ea nego \u0161to nama zvu\u010di. Ako ga ka\u017ee\u0161 nekome u lice, ra\u010dunaj na sva\u0111u, a mo\u017eda i na prijavu policiji. Nikad nikome na poslu, u slu\u017ebi ili u kom\u0161iluku."},ex:{de:"Was f\xfcr ein Arschloch! Er hat einfach meinen Platz genommen.",sr:"Kakav \u0161upak! Jednostavno mi je uzeo mesto.",hr:"Kakav \u0161upak! Jednostavno mi je uzeo mjesto.",bs:"Kakav \u0161upak! Jednostavno mi je uzeo mjesto.",me:"Kakav \u0161upak! Jednostavno mi je uzeo mjesto."}},{de:"leck mich",sr:"ma jebi se",lvl:3,note:{sr:"Skra\u0107eno od \"Leck mich am Arsch\", doslovno \"poli\u017ei me...\", ostatak zna\u0161. Ima ga \u010dak i u jednoj Geteovoj drami, ali i dalje zvu\u010di jako grubo. Ka\u017ee se kad ti je svega dosta, ali nikad \u0161efu, stanodavcu ili slu\u017ebeniku, osim ako \u017eeli\u0161 da izgubi\u0161 posao, stan ili termin.",hr:"Skra\u0107eno od \"Leck mich am Arsch\", doslovno \"poli\u017ei me...\", ostatak zna\u0161. Ima ga \u010dak i u jednoj Goetheovoj drami, ali i dalje zvu\u010di jako grubo. Ka\u017ee se kad ti je svega dosta, ali nikad \u0161efu, stanodavcu ili slu\u017ebeniku, osim ako \u017eeli\u0161 izgubiti posao, stan ili termin.",bs:"Skra\u0107eno od \"Leck mich am Arsch\", doslovno \"poli\u017ei me...\", ostatak zna\u0161. Ima ga \u010dak i u jednoj Goetheovoj drami, ali i dalje zvu\u010di jako grubo. Ka\u017ee se kad ti je svega dosta, ali nikad \u0161efu, stanodavcu ili slu\u017ebeniku, osim ako \u017eeli\u0161 izgubiti posao, stan ili termin.",me:"Skra\u0107eno od \"Leck mich am Arsch\", doslovno \"poli\u017ei me...\", ostatak zna\u0161. Ima ga \u010dak i u jednoj Geteovoj drami, ali i dalje zvu\u010di jako grubo. Ka\u017ee se kad ti je svega dosta, ali nikad \u0161efu, stanodavcu ili slu\u017ebeniku, osim ako \u017eeli\u0161 da izgubi\u0161 posao, stan ili termin."},ex:{de:"Ach, leck mich doch! Ich mache das nicht.",sr:"Ma jebi se! Ne\u0107u to da radim.",hr:"Ma jebi se! Ne\u0107u to raditi.",bs:"Ma jebi se! Ne\u0107u to raditi."}},{de:"du spinnst wohl",sr:"jesi li ti normalan?",lvl:1,note:{sr:"Od glagola \"spinnen\", presti kao pauk, a u govoru: biti lud. Zna\u010di \"jesi li ti normalan?\" i obi\u010dno se ka\u017ee napola u \u0161ali, kad drug predlo\u017ei ne\u0161to suludo. Nepoznatima i nadre\u0111enima to nikako ne govori.",hr:"Od glagola \"spinnen\", presti kao pauk, a u govoru: biti lud. Zna\u010di \"jesi li ti normalan?\" i obi\u010dno se ka\u017ee napola u \u0161ali, kad prijatelj predlo\u017ei ne\u0161to suludo. Nepoznatima i nadre\u0111enima to nikako ne govori.",bs:"Od glagola \"spinnen\", presti kao pauk, a u govoru: biti lud. Zna\u010di \"jesi li ti normalan?\" i obi\u010dno se ka\u017ee napola u \u0161ali, kad drug predlo\u017ei ne\u0161to suludo. Nepoznatima i nadre\u0111enima to nikako ne govori.",me:"Od glagola \"spinnen\", presti kao pauk, a u govoru: biti lud. Zna\u010di \"jesi li ti normalan?\" i obi\u010dno se ka\u017ee napola u \u0161ali, kad drug predlo\u017ei ne\u0161to suludo. Nepoznatima i nadre\u0111enima to nikako ne govori."},ex:{de:"Du spinnst wohl! Ich gehe doch nicht um f\xfcnf Uhr morgens joggen.",sr:"Jesi li ti normalan? Ne\u0107u da tr\u010dim u pet ujutro.",hr:"Jesi li ti normalan? Ne\u0107u tr\u010dati u pet ujutro.",bs:"Jesi li ti normalan? Ne\u0107u tr\u010dati u pet ujutro."}},{de:"so ein Mist!",sr:"kakav peh!",lvl:1,note:{sr:"\"Kakav peh!\" kad ti ne\u0161to pokvari dan: otkazan voz, ki\u0161a na izletu, zaboravljen klju\u010d. Potpuno bezopasno, mo\u017ee\u0161 ga re\u0107i i pred kolegama, pa \u010dak i pred \u0161efom kad ti se pokvari ra\u010dunar.",hr:"\"Kakav peh!\" kad ti ne\u0161to pokvari dan: otkazan vlak, ki\u0161a na izletu, zaboravljen klju\u010d. Potpuno bezopasno, mo\u017ee\u0161 ga re\u0107i i pred kolegama, pa \u010dak i pred \u0161efom kad ti se pokvari ra\u010dunalo.",bs:"\"Kakav peh!\" kad ti ne\u0161to pokvari dan: otkazan voz, ki\u0161a na izletu, zaboravljen klju\u010d. Potpuno bezopasno, mo\u017ee\u0161 ga re\u0107i i pred kolegama, pa \u010dak i pred \u0161efom kad ti se pokvari ra\u010dunar.",me:"\"Kakav peh!\" kad ti ne\u0161to pokvari dan: otkazan voz, ki\u0161a na izletu, zaboravljen klju\u010d. Potpuno bezopasno, mo\u017ee\u0161 ga re\u0107i i pred kolegama, pa \u010dak i pred \u0161efom kad ti se pokvari ra\u010dunar."},ex:{de:"So ein Mist, der Zug f\xe4llt schon wieder aus!",sr:"Kakav peh, voz je opet otkazan!",hr:"Kakav peh, vlak je opet otkazan!"}},{de:"Schei\xdf drauf!",sr:"jebiga",lvl:2,note:{sr:"Isto \u0161to i na\u0161e \"jebiga\", ali Nemci ga govore mnogo re\u0111e i zvu\u010di im grublje nego nama \"jebiga\". Me\u0111u prijateljima prolazi, a na poslu i pred starijima ga izbegavaj.",hr:"Isto \u0161to i na\u0161e \"jebiga\", ali Nijemci ga govore puno rje\u0111e i zvu\u010di im grublje nego nama \"jebiga\". Me\u0111u prijateljima prolazi, a na poslu i pred starijima ga izbjegavaj.",bs:"Isto \u0161to i na\u0161e \"jebiga\", ali Nijemci ga govore mnogo rje\u0111e i zvu\u010di im grublje nego nama \"jebiga\". Me\u0111u prijateljima prolazi, a na poslu i pred starijima ga izbjegavaj.",me:"Isto \u0161to i na\u0161e \"jebiga\", ali Nijemci ga govore mnogo rje\u0111e i zvu\u010di im grublje nego nama \"jebiga\". Me\u0111u prijateljima prolazi, a na poslu i pred starijima ga izbjegavaj."},ex:{de:"Schei\xdf drauf, wir bestellen einfach Pizza.",sr:"Jebiga, hajde da naru\u010dimo picu.",hr:"Jebiga, naru\u010dimo pizzu."}},{de:"Ach du Schei\xdfe!",sr:"jebote!",lvl:2,note:{sr:"Uzvik \u0161oka kad vidi\u0161 ne\u0161to lo\u0161e, kao na\u0161e \"jebote!\" ili \"uh, sranje!\". Izleti i najpristojnijim Nemcima, ali ne pred decom, \u0161efom ili mu\u0161terijama.",hr:"Uzvik \u0161oka kad vidi\u0161 ne\u0161to lo\u0161e, kao na\u0161e \"jebote!\" ili \"uh, sranje!\". Izleti i najpristojnijim Nijemcima, ali ne pred djecom, \u0161efom ili kupcima.",bs:"Uzvik \u0161oka kad vidi\u0161 ne\u0161to lo\u0161e, kao na\u0161e \"jebote!\" ili \"uh, sranje!\". Izleti i najpristojnijim Nijemcima, ali ne pred djecom, \u0161efom ili mu\u0161terijama.",me:"Uzvik \u0161oka kad vidi\u0161 ne\u0161to lo\u0161e, kao na\u0161e \"jebote!\" ili \"uh, sranje!\". Izleti i najpristojnijim Nijemcima, ali ne pred djecom, \u0161efom ili mu\u0161terijama."},ex:{de:"Ach du Schei\xdfe, mein Auto ist weg!",sr:"Jebote, nema mi auta!"}}]},jam:{title:"Swear words",tip:"These words are far stronger in Jamaica than they sound to British ears. The 'claat' words (bloodclaat, bumboclaat, raasclaat) are serious insults that can end friendships or start fights, and swearing in public is still an offence under Jamaican law. Learn them so you can understand music, films and family arguments, not to use them yourself. Heat goes from \ud83c\udf36\ufe0f mild to \ud83c\udf36\ufe0f\ud83c\udf36\ufe0f\ud83c\udf36\ufe0f strong.",items:[{jam:"bloodclaat",en:"very strong curse (lit. blood cloth)",lvl:3,note:"One of the three 'cloth' curses, at least as strong as the f-word, and it can start a real fight in Jamaica.",ex:{jam:"Bloodclaat! Mi lose mi wallet.",en:"Bloody hell! I've lost my wallet. (far stronger)"}},{jam:"bumboclaat",en:"the strongest curse (lit. bottom cloth)",lvl:3,note:"Often called the strongest Jamaican curse; online it became the joke spelling 'bombaclat', but in Jamaica it is still deeply offensive.",ex:{jam:"Wah di bumboclaat dis?",en:"What the hell is this? (far ruder)"}},{jam:"raasclaat",en:"very strong curse (lit. arse cloth)",lvl:3,note:"Shouted in anger or shock and stuck onto other words for force; many Jamaicans, especially churchgoers, find it shocking.",ex:{jam:"Move yuh raasclaat car from mi gate!",en:"Move your bloody car from my gate! (far ruder)"}},{jam:"rass",en:"damn! (rude, lit. arse)",lvl:2,note:"The short form, heard alone or in 'kiss mi rass'; still rude, but a step down from the full claat words.",ex:{jam:"Rass! Di pot bun.",en:"Damn! The pot's burnt."}},{jam:"yuh mumma",en:"your mum! (insult)",lvl:2,note:"Insulting someone's mother is a quick way to start a real row, so it is never harmless banter with strangers.",ex:{jam:"Im seh 'yuh mumma' an di whole place get quiet.",en:"He said 'your mum' and the whole place went quiet."}},{jam:"dutty",en:"nasty, low (as an insult)",lvl:1,note:"Called at a person, it means low or nasty, not just dirty; rude, but not a swear word.",ex:{jam:"Gweh, yuh dutty liar!",en:"Go away, you nasty liar!"}},{jam:"eediat",en:"idiot",lvl:1,note:"The everyday Jamaican 'idiot': rude, but heard at home and in the street all the time.",ex:{jam:"Yuh eediat, yuh lef di gate open!",en:"You idiot, you left the gate open!"}},{jam:"badmind",en:"envious, spiteful",lvl:1,note:"For people who can't stand to see others do well; a common accusation, not a swear word.",ex:{jam:"Dem too badmind, dem cyaa stand fi see wi do well.",en:"They're so spiteful, they can't bear to see us do well."}},{jam:"wutless",en:"worthless, good-for-nothing",lvl:1,note:"A stinging put-down for someone who is lazy or treats people badly.",ex:{jam:"Im wutless, im nuh help wid nutten.",en:"He's useless, he doesn't help with anything."}},{jam:"rhaatid",en:"goodness! (mild)",lvl:1,note:"A mild cry of surprise or annoyance that even grandparents use.",ex:{jam:"Rhaatid! Yuh grow tall, man!",en:"Goodness! You've grown tall!"}},{jam:"kiss mi neck",en:"well I never!",lvl:1,note:"A mild cry of surprise, and a polite stand-in for ruder 'kiss mi...' phrases.",ex:{jam:"Kiss mi neck! A yuh dat?",en:"Well I never! Is that you?"}},{jam:"blouse an skirt",en:"blimey! (polite stand-in)",lvl:1,note:"It sounds a bit like the claat words, so people can let off steam without really swearing.",ex:{jam:"Blouse an skirt! Di price gone up again.",en:"Blimey! The price has gone up again."}},{jam:"kiss teeth",en:"suck your teeth (rude sound)",lvl:1,note:"A long sucking sound through the teeth (written kmt) that shows contempt; doing it to an elder is very rude.",ex:{jam:"Shi kiss teeth an walk out.",en:"She sucked her teeth and walked out."}},{jam:"cho",en:"tsk! oh, come on!",lvl:1,note:"A quick sound of irritation, about as strong as 'ugh'.",ex:{jam:"Cho, man, mi forget mi key!",en:"Oh, come on, I forgot my key!"}}]},sl:{title:{sr:"Psovke",hr:"Psovke",bs:"Psovke",me:"Psovke"},tip:{sr:"Slovenci psuju bla\u017ee od nas: doma\u0107e psovke su uglavnom o \u0111avolu (hudi\u010d, vrag) i bezazleni uzvici kao \"Madona!\". Ja\u010de psovke su skoro sve pozajmljene od nas, pa \u0107e te svaki Slovenac razumeti kad opsuje\u0161 na na\u0161em. Zlatna pravila: nikad na poslu, nikad pred slu\u017ebenicima i policijom, i nikad sa ljudima kojima persira\u0161 (na \"vi\"). Ja\u010dina ide od \ud83c\udf36\ufe0f (blago) do \ud83c\udf36\ufe0f\ud83c\udf36\ufe0f\ud83c\udf36\ufe0f (jako).",hr:"Slovenci psuju bla\u017ee od nas: doma\u0107e psovke uglavnom su o vragu (hudi\u010d, vrag) i bezazleni uzvici poput \"Madona!\". Ja\u010de psovke gotovo su sve posu\u0111ene od nas, pa \u0107e te svaki Slovenac razumjeti kad opsuje\u0161 na na\u0161em. Zlatna pravila: nikad na poslu, nikad pred slu\u017ebenicima i policijom i nikad s ljudima s kojima si na \"vi\". Ja\u010dina ide od \ud83c\udf36\ufe0f (blago) do \ud83c\udf36\ufe0f\ud83c\udf36\ufe0f\ud83c\udf36\ufe0f (jako).",bs:"Slovenci psuju bla\u017ee od nas: doma\u0107e psovke su uglavnom o \u0111avolu (hudi\u010d, vrag) i bezazleni uzvici kao \"Madona!\". Ja\u010de psovke su skoro sve pozajmljene od nas, pa \u0107e te svaki Slovenac razumjeti kad opsuje\u0161 na na\u0161em. Zlatna pravila: nikad na poslu, nikad pred slu\u017ebenicima i policijom i nikad s ljudima kojima persira\u0161 (na \"vi\"). Ja\u010dina ide od \ud83c\udf36\ufe0f (blago) do \ud83c\udf36\ufe0f\ud83c\udf36\ufe0f\ud83c\udf36\ufe0f (jako).",me:"Slovenci psuju bla\u017ee od nas: doma\u0107e psovke su uglavnom o \u0111avolu (hudi\u010d, vrag) i bezazleni uzvici kao \"Madona!\". Ja\u010de psovke su skoro sve pozajmljene od nas, pa \u0107e te svaki Slovenac razumjeti kad opsuje\u0161 na na\u0161em. Zlatna pravila: nikad na poslu, nikad pred slu\u017ebenicima i policijom, i nikad sa ljudima kojima persira\u0161 (na \"vi\"). Ja\u010dina ide od \ud83c\udf36\ufe0f (blago) do \ud83c\udf36\ufe0f\ud83c\udf36\ufe0f\ud83c\udf36\ufe0f (jako)."},items:[{sl:"Madona!",sr:"Bo\u017ee!, joj!",lvl:1,note:{sr:"Jedan od naj\u010de\u0161\u0107ih slovena\u010dkih uzvika za iznena\u0111enje ili nervozu. Blago, \u010duje se i od baka i na poslu.",hr:"Jedan od naj\u010de\u0161\u0107ih slovenskih uzvika za iznena\u0111enje ili nervozu. Blago, \u010duje se i od baka i na poslu.",bs:"Jedan od naj\u010de\u0161\u0107ih slovena\u010dkih uzvika za iznena\u0111enje ili nervozu. Blago, \u010duje se i od nana i na poslu.",me:"Jedan od naj\u010de\u0161\u0107ih slovena\u010dkih uzvika za iznena\u0111enje ili nervozu. Blago, \u010duje se i od baka i na poslu."},ex:{sl:"Madona, kako je vro\u010de!",sr:"Bo\u017ee, kako je vru\u0107e!"}},{sl:"Prekleto!",sr:"do\u0111avola!",hr:"dovraga!",bs:"dovraga!",lvl:1,note:{sr:"Doslovno \"prokleto\". Blaga psovka kad ne\u0161to po\u0111e naopako, prolazi pred ve\u0107inom ljudi.",hr:"Doslovno \"prokleto\". Blaga psovka kad ne\u0161to po\u0111e naopako, prolazi pred ve\u0107inom ljudi.",bs:"Doslovno \"prokleto\". Blaga psovka kad ne\u0161to po\u0111e naopako, prolazi pred ve\u0107inom ljudi.",me:"Doslovno \"prokleto\". Blaga psovka kad ne\u0161to po\u0111e naopako, prolazi pred ve\u0107inom ljudi."},ex:{sl:"Prekleto, spet sem zamudil avtobus!",sr:"Do\u0111avola, opet sam propustio autobus!",hr:"Dovraga, opet sam propustio autobus!",bs:"Dovraga, opet sam propustio autobus!"}},{sl:"Kaj za hudi\u010da?",sr:"koji \u0111avo?",hr:"koji vrag?",bs:"koji vrag?",lvl:1,note:{sr:"\"Hudi\u010d\" je \u0111avo. Kao na\u0161e \"Koji \u0111avo?\", kad si iznena\u0111en ili ljut.",hr:"\"Hudi\u010d\" je vrag. Kao na\u0161e \"Koji vrag?\", kad si iznena\u0111en ili ljut.",bs:"\"Hudi\u010d\" je \u0111avo. Kao na\u0161e \"Koji vrag?\", kad si iznena\u0111en ili ljut.",me:"\"Hudi\u010d\" je \u0111avo. Kao na\u0161e \"Koji \u0111avo?\", kad si iznena\u0111en ili ljut."},ex:{sl:"Kaj za hudi\u010da dela\u0161 tukaj?",sr:"\u0160ta, do\u0111avola, radi\u0161 ovde?",hr:"\u0160to, dovraga, radi\u0161 ovdje?",bs:"\u0160ta, dovraga, radi\u0161 ovdje?",me:"\u0160ta, do\u0111avola, radi\u0161 ovdje?"}},{sl:"\u0160ment!",sr:"do\u0111avola! (vrlo blago)",hr:"dovraga! (vrlo blago)",bs:"dovraga! (vrlo blago)",lvl:1,note:{sr:"Vrlo blaga, pomalo staromodna psovka. Ka\u017ee se kad ti ne\u0161to ispadne ili zaboravi\u0161 klju\u010deve. Mo\u017ee i pred decom.",hr:"Vrlo blaga, pomalo staromodna psovka. Ka\u017ee se kad ti ne\u0161to ispadne ili zaboravi\u0161 klju\u010deve. Mo\u017ee i pred djecom.",bs:"Vrlo blaga, pomalo staromodna psovka. Ka\u017ee se kad ti ne\u0161to ispadne ili zaboravi\u0161 klju\u010deve. Mo\u017ee i pred djecom.",me:"Vrlo blaga, pomalo staromodna psovka. Ka\u017ee se kad ti ne\u0161to ispadne ili zaboravi\u0161 klju\u010deve. Mo\u017ee i pred djecom."},ex:{sl:"\u0160ment, klju\u010de sem pozabila doma!",sr:"Do\u0111avola, zaboravila sam klju\u010deve kod ku\u0107e!",hr:"Dovraga, zaboravila sam klju\u010deve kod ku\u0107e!",bs:"Dovraga, zaboravila sam klju\u010deve kod ku\u0107e!"}},{sl:"bedak",sr:"budala, glupak",lvl:1,note:{sr:"Najobi\u010dnija blaga uvreda, kao na\u0161e \"budala\". Me\u0111u prijateljima ide i iz \u0161ale.",hr:"Najobi\u010dnija blaga uvreda, kao na\u0161e \"budala\". Me\u0111u prijateljima ide i iz \u0161ale.",bs:"Najobi\u010dnija blaga uvreda, kao na\u0161e \"budala\". Me\u0111u prijateljima ide i iz \u0161ale.",me:"Najobi\u010dnija blaga uvreda, kao na\u0161e \"budala\". Me\u0111u prijateljima ide i iz \u0161ale."},ex:{sl:"Ne bodi bedak, saj je samo igra.",sr:"Ne budi budala, to je samo igra."}},{sl:"Pejt se solit!",sr:"ma idi!, gubi se!",lvl:1,note:{sr:"Doslovno \"Idi se posoli!\". Tipi\u010dno slovena\u010dki na\u010din da nekog po\u0161alje\u0161 dalje, vi\u0161e sme\u0161an nego uvredljiv.",hr:"Doslovno \"Idi se posoliti!\". Tipi\u010dno slovenski na\u010din da nekoga po\u0161alje\u0161 dalje, vi\u0161e smije\u0161an nego uvredljiv.",bs:"Doslovno \"Idi se posoli!\". Tipi\u010dno slovena\u010dki na\u010din da nekog po\u0161alje\u0161 dalje, vi\u0161e smije\u0161an nego uvredljiv.",me:"Doslovno \"Idi se posoli!\". Tipi\u010dno slovena\u010dki na\u010din da nekog po\u0161alje\u0161 dalje, vi\u0161e smije\u0161an nego uvredljiv."},ex:{sl:"Pejt se solit s takimi idejami!",sr:"Ma idi sa takvim idejama!",hr:"Ma idi s takvim idejama!",bs:"Ma idi s takvim idejama!"}},{sl:"Briga me.",sr:"ba\u0161 me briga",lvl:1,note:{sr:"Isto kao kod nas i zna\u010di isto. Nije psovka, ali zvu\u010di nezainteresovano, pa ga ne govori \u0161efu.",hr:"Isto kao kod nas i zna\u010di isto. Nije psovka, ali zvu\u010di nezainteresirano, pa ga ne govori \u0161efu.",bs:"Isto kao kod nas i zna\u010di isto. Nije psovka, ali zvu\u010di nezainteresovano, pa ga ne govori \u0161efu.",me:"Isto kao kod nas i zna\u010di isto. Nije psovka, ali zvu\u010di nezainteresovano, pa ga ne govori \u0161efu."},ex:{sl:"Briga me, kaj si mislijo sosedje.",sr:"Ba\u0161 me briga \u0161ta misle kom\u0161ije.",hr:"Ba\u0161 me briga \u0161to misle susjedi."}},{sl:"drek",sr:"sme\u0107e, govno (blago)",lvl:1,note:{sr:"Od nema\u010dkog \"Dreck\". Za ne\u0161to lo\u0161e ili bezvredno: \"To je drek.\" Bla\u017ee od \"sranje\".",hr:"Od njema\u010dkoga \"Dreck\". Za ne\u0161to lo\u0161e ili bezvrijedno: \"To je drek.\" Bla\u017ee od \"sranje\".",bs:"Od njema\u010dkog \"Dreck\". Za ne\u0161to lo\u0161e ili bezvrijedno: \"To je drek.\" Bla\u017ee od \"sranje\".",me:"Od njema\u010dkog \"Dreck\". Za ne\u0161to lo\u0161e ili bezvrijedno: \"To je drek.\" Bla\u017ee od \"sranje\"."},ex:{sl:"Ta film je bil \u010disti drek.",sr:"Taj film je bio \u010disto sme\u0107e."}},{sl:"A si nor?",sr:"jesi li normalan?",lvl:1,note:{sr:"Doslovno \"Jesi li lud?\". Kad ti neko predlo\u017ei ne\u0161to suludo. Me\u0111u prijateljima sasvim normalno.",hr:"Doslovno \"Jesi li lud?\". Kad ti netko predlo\u017ei ne\u0161to suludo. Me\u0111u prijateljima posve normalno.",bs:"Doslovno \"Jesi li lud?\". Kad ti neko predlo\u017ei ne\u0161to suludo. Me\u0111u prijateljima sasvim normalno.",me:"Doslovno \"Jesi li lud?\". Kad ti neko predlo\u017ei ne\u0161to suludo. Me\u0111u prijateljima sasvim normalno."},ex:{sl:"A si nor? Zunaj je minus deset!",sr:"Jesi li normalan? Napolju je minus deset!",hr:"Jesi li normalan? Vani je minus deset!",bs:"Jesi li normalan? Vani je minus deset!"}},{sl:"Utihni!",sr:"\u0107uti!",hr:"\u0161uti!",bs:"\u0161uti!",lvl:1,note:{sr:"Direktno i grubo, ali bez psovke. Ja\u010da verzija je \"Dr\u017e gobec!\".",hr:"Izravno i grubo, ali bez psovke. Ja\u010da verzija je \"Dr\u017e gobec!\".",bs:"Direktno i grubo, ali bez psovke. Ja\u010da verzija je \"Dr\u017e gobec!\".",me:"Direktno i grubo, ali bez psovke. Ja\u010da verzija je \"Dr\u017e gobec!\"."},ex:{sl:"Utihni, gledam film!",sr:"\u0106uti, gledam film!",hr:"\u0160uti, gledam film!",bs:"\u0160uti, gledam film!"}},{sl:"Sranje!",sr:"sranje",lvl:2,note:{sr:"Isto kao kod nas. Uzvik kad ne\u0161to krene naopako. Me\u0111u prijateljima normalno, na poslu i pred nepoznatima ne.",hr:"Isto kao kod nas. Uzvik kad ne\u0161to krene naopako. Me\u0111u prijateljima normalno, na poslu i pred nepoznatima ne.",bs:"Isto kao kod nas. Uzvik kad ne\u0161to krene naopako. Me\u0111u prijateljima normalno, na poslu i pred nepoznatima ne.",me:"Isto kao kod nas. Uzvik kad ne\u0161to krene naopako. Me\u0111u prijateljima normalno, na poslu i pred nepoznatima ne."},ex:{sl:"Sranje, pozabil sem denarnico!",sr:"Sranje, zaboravio sam nov\u010danik!"}},{sl:"Jebemti!",sr:"jebote!",lvl:2,note:{sr:"Pozajmljeno od nas i potpuno odoma\u0107eno: \u010du\u0107e\u0161 ga na svakom koraku, kao uzvik iznena\u0111enja i kao psovku. Zato Slovenci odmah prepoznaju i na\u0161e ja\u010de psovke.",hr:"Posu\u0111eno od nas i potpuno udoma\u0107eno: \u010dut \u0107e\u0161 ga na svakom koraku, kao uzvik iznena\u0111enja i kao psovku. Zato Slovenci odmah prepoznaju i na\u0161e ja\u010de psovke.",bs:"Pozajmljeno od nas i potpuno odoma\u0107eno: \u010dut \u0107e\u0161 ga na svakom koraku, kao uzvik iznena\u0111enja i kao psovku. Zato Slovenci odmah prepoznaju i na\u0161e ja\u010de psovke.",me:"Pozajmljeno od nas i potpuno odoma\u0107eno: \u010du\u0107e\u0161 ga na svakom koraku, kao uzvik iznena\u0111enja i kao psovku. Zato Slovenci odmah prepoznaju i na\u0161e ja\u010de psovke."},ex:{sl:"Jebemti, kako je drago!",sr:"Jebote, kako je skupo!"}},{sl:"Pizda!",sr:"jebote! (kao uzvik)",lvl:2,note:{sr:"Vrlo \u010dest slovena\u010dki uzvik kad ne\u0161to po\u0111e naopako ili te ne\u0161to iznenadi. Kao uzvik je me\u0111u mladima dosta obi\u010dan, ali je vulgaran, a upu\u0107en nekoj osobi je te\u0161ka uvreda.",hr:"Vrlo \u010dest slovenski uzvik kad ne\u0161to po\u0111e naopako ili te ne\u0161to iznenadi. Kao uzvik je me\u0111u mladima dosta obi\u010dan, ali je vulgaran, a upu\u0107en nekoj osobi te\u0161ka je uvreda.",bs:"Vrlo \u010dest slovena\u010dki uzvik kad ne\u0161to po\u0111e naopako ili te ne\u0161to iznenadi. Kao uzvik je me\u0111u mladima dosta obi\u010dan, ali je vulgaran, a upu\u0107en nekoj osobi je te\u0161ka uvreda.",me:"Vrlo \u010dest slovena\u010dki uzvik kad ne\u0161to po\u0111e naopako ili te ne\u0161to iznenadi. Kao uzvik je me\u0111u mladima dosta obi\u010dan, ali je vulgaran, a upu\u0107en nekoj osobi je te\u0161ka uvreda."},ex:{sl:"Pizda, kako je mrzlo!",sr:"Jebote, kako je hladno!"}},{sl:"A me zajebava\u0161?",sr:"zajebava\u0161 li me?",lvl:2,note:{sr:"Pozajmljeno od nas, zna\u010di isto. Kad ti ne\u0161to zvu\u010di kao lo\u0161a \u0161ala. Bla\u017ea verzija je \"A se heca\u0161?\" (\u0160ali\u0161 se?).",hr:"Posu\u0111eno od nas, zna\u010di isto. Kad ti ne\u0161to zvu\u010di kao lo\u0161a \u0161ala. Bla\u017ea verzija je \"A se heca\u0161?\" (\u0160ali\u0161 se?).",bs:"Pozajmljeno od nas, zna\u010di isto. Kad ti ne\u0161to zvu\u010di kao lo\u0161a \u0161ala. Bla\u017ea verzija je \"A se heca\u0161?\" (\u0160ali\u0161 se?).",me:"Pozajmljeno od nas, zna\u010di isto. Kad ti ne\u0161to zvu\u010di kao lo\u0161a \u0161ala. Bla\u017ea verzija je \"A se heca\u0161?\" (\u0160ali\u0161 se?)."},ex:{sl:"A me zajebava\u0161? Spet ni vode?",sr:"Zajebava\u0161 li me? Opet nema vode?"}},{sl:"kreten",sr:"kreten",lvl:2,note:{sr:"Kao kod nas. U Sloveniji se \u010duje vrlo \u010desto, naro\u010dito u saobra\u0107aju. Uvredljivo, pa ga ne govori nikome u lice.",hr:"Kao kod nas. U Sloveniji se \u010duje vrlo \u010desto, osobito u prometu. Uvredljivo, pa ga ne govori nikome u lice.",bs:"Kao kod nas. U Sloveniji se \u010duje vrlo \u010desto, naro\u010dito u saobra\u0107aju. Uvredljivo, pa ga ne govori nikome u lice.",me:"Kao kod nas. U Sloveniji se \u010duje vrlo \u010desto, naro\u010dito u saobra\u0107aju. Uvredljivo, pa ga ne govori nikome u lice."},ex:{sl:"Kak\u0161en kreten! Parkiral je na mojem mestu.",sr:"Kakav kreten! Parkirao se na moje mesto.",hr:"Kakav kreten! Parkirao je na moje mjesto.",bs:"Kakav kreten! Parkirao se na moje mjesto.",me:"Kakav kreten! Parkirao se na moje mjesto."}},{sl:"Dr\u017e gobec!",sr:"za\u010depi gubicu!",lvl:2,note:{sr:"\"Gobec\" je nju\u0161ka. Grubo i bezobrazno, samo u sva\u0111i ili iz \u0161ale me\u0111u veoma bliskim prijateljima.",hr:"\"Gobec\" je nju\u0161ka. Grubo i bezobrazno, samo u sva\u0111i ili iz \u0161ale me\u0111u vrlo bliskim prijateljima.",bs:"\"Gobec\" je nju\u0161ka. Grubo i bezobrazno, samo u sva\u0111i ili iz \u0161ale me\u0111u veoma bliskim prijateljima.",me:"\"Gobec\" je nju\u0161ka. Grubo i bezobrazno, samo u sva\u0111i ili iz \u0161ale me\u0111u veoma bliskim prijateljima."},ex:{sl:"Dr\u017e gobec, nih\u010de te ni ni\u010d vpra\u0161al!",sr:"Za\u010depi, niko te ni\u0161ta nije pitao!",hr:"Za\u010depi, nitko te ni\u0161ta nije pitao!"}},{sl:"Jebi se!",sr:"jebi se!",lvl:3,note:{sr:"Pozajmljeno i razume se svuda, ali je jako grubo. Kad ga ka\u017ee\u0161, sva\u0111a je po\u010dela.",hr:"Posu\u0111eno i razumije se posvuda, ali je jako grubo. Kad ga ka\u017ee\u0161, sva\u0111a je po\u010dela.",bs:"Pozajmljeno i razumije se svugdje, ali je jako grubo. Kad ga ka\u017ee\u0161, sva\u0111a je po\u010dela.",me:"Pozajmljeno i razumije se svuda, ali je jako grubo. Kad ga ka\u017ee\u0161, sva\u0111a je po\u010dela."},ex:{sl:"Jebi se, nikamor ne grem s tabo!",sr:"Jebi se, ne idem nigde s tobom!",hr:"Jebi se, ne idem nikamo s tobom!",bs:"Jebi se, ne idem nigdje s tobom!",me:"Jebi se, ne idem nigdje s tobom!"}},{sl:"Odjebi!",sr:"odjebi!",lvl:3,note:{sr:"Isto kao kod nas i jednako grubo. Samo iz \u0161ale sa najboljim drugom, nikad sa nekim koga ne poznaje\u0161 dobro.",hr:"Isto kao kod nas i jednako grubo. Samo iz \u0161ale s najboljim prijateljem, nikad s nekim koga ne poznaje\u0161 dobro.",bs:"Isto kao kod nas i jednako grubo. Samo iz \u0161ale s najboljim drugom, nikad s nekim koga ne poznaje\u0161 dobro.",me:"Isto kao kod nas i jednako grubo. Samo iz \u0161ale sa najboljim drugom, nikad sa nekim koga ne poznaje\u0161 dobro."},ex:{sl:"Odjebi in me pusti pri miru!",sr:"Odjebi i ostavi me na miru!"}},{sl:"Pizda ti materna!",sr:"pi\u010dka ti materina!",lvl:3,note:{sr:"Pozajmljeno od nas, najja\u010da uobi\u010dajena psovka u Sloveniji. Slovenci je \u010desto izgovaraju kao uzvik, kad se pokvari auto ili kompjuter, ali pred bilo kim ko nije blizak prijatelj ne dolazi u obzir.",hr:"Posu\u0111eno od nas, najja\u010da uobi\u010dajena psovka u Sloveniji. Slovenci je \u010desto izgovaraju kao uzvik, kad se pokvari auto ili ra\u010dunalo, ali pred bilo kim tko nije blizak prijatelj ne dolazi u obzir.",bs:"Pozajmljeno od nas, najja\u010da uobi\u010dajena psovka u Sloveniji. Slovenci je \u010desto izgovaraju kao uzvik, kad se pokvari auto ili kompjuter, ali pred bilo kim ko nije blizak prijatelj ne dolazi u obzir.",me:"Pozajmljeno od nas, najja\u010da uobi\u010dajena psovka u Sloveniji. Slovenci je \u010desto izgovaraju kao uzvik, kad se pokvari auto ili kompjuter, ali pred bilo kim ko nije blizak prijatelj ne dolazi u obzir."},ex:{sl:"Pizda ti materna, spet se je pokvaril!",sr:"Pi\u010dka ti materina, opet se pokvario!"}}]}}},1322,[]);